-- Legacy encounter regression; transaction rollback restores the current default.
alter table phi.encounters alter column content_version set default 'demo-draft-2026-09-21';
select no_plan();
insert into auth.users(id,email,role,aud) values('92000000-0000-4000-8000-000000000001','worker-sql@demo.invalid','authenticated','authenticated');
insert into app.staff_accounts(user_id,synthetic_key) values('92000000-0000-4000-8000-000000000001','SYN-WORKER-SQL');
insert into app.sites(id,name) values('92000000-0000-4000-8000-000000000002','SYN Worker SQL');
insert into phi.patients(id,site_id,synthetic_identifier,display_name,year_of_birth,is_synthetic) values('92000000-0000-4000-8000-000000000003','92000000-0000-4000-8000-000000000002','SYN-WORKER-SQL-P','Fictional worker patient',1974,true);
insert into phi.encounters(id,site_id,patient_id,assigned_to,status,consent_at,notice_version,cap_hash,cap_expires,intake,version) values('92000000-0000-4000-8000-000000000004','92000000-0000-4000-8000-000000000002','92000000-0000-4000-8000-000000000003','92000000-0000-4000-8000-000000000001','queued',now(),'synthetic-fixture-v1',encode(extensions.digest(repeat('b',64),'sha256'),'hex'),now()+interval '2 hours','{"name":"Fictional worker patient","age":52,"sex":"Male","suppliedBy":"patient","enteredBy":"patient","relationship":"","stage":6,"answers":{"vomit_blood":"Yes"}}',1);
insert into phi.demo_reports(id,encounter_id,site_id,name,mime,body,fields,quality) values('92000000-0000-4000-8000-000000000005','92000000-0000-4000-8000-000000000004','92000000-0000-4000-8000-000000000002','Fictional source.pdf','application/pdf',repeat('A',16),'[{"id":"f1","label":"Haemoglobin","value":"10.4","unit":"g/dL","page":1,"sourceText":"Haemoglobin 10.4 g/dL","confidence":"text-extracted","verified":true,"date":""}]','Synthetic SQL test');
-- Uploads always begin unverified; this fixture explicitly simulates subsequent staff verification.
update phi.demo_reports set extraction_status='completed' where id='92000000-0000-4000-8000-000000000005';
update phi.demo_reports set fields='[{"id":"f1","label":"Haemoglobin","value":"10.4","unit":"g/dL","page":1,"sourceText":"Haemoglobin 10.4 g/dL","confidence":"text-extracted","verified":true,"date":""}]' where id='92000000-0000-4000-8000-000000000005';
insert into phi.demo_jobs(id,encounter_id,site_id,source_version) values('92000000-0000-4000-8000-000000000006','92000000-0000-4000-8000-000000000004','92000000-0000-4000-8000-000000000002',1);
select throws_ok($$update phi.demo_jobs set snapshot='{}' where id='92000000-0000-4000-8000-000000000006'$$,'P0001','Job source is immutable','queued evidence snapshot cannot be rewritten');
update phi.demo_reports set fields='[]' where id='92000000-0000-4000-8000-000000000005';
set local role anon;
select throws_ok($$select api.demo_worker('claim')$$,'42501',null,'patient cannot execute privileged worker');
select is(api.demo_action('report_get','92000000-0000-4000-8000-000000000004',repeat('a',64),'{"reportId":"92000000-0000-4000-8000-000000000005"}')->>'ok','false','original report denied to wrong capability');
reset role;
set local role service_role;
select set_config('test.job',(api.demo_worker('claim','92000000-0000-4000-8000-000000000006')->'data')::text,true);
select is(current_setting('test.job')::jsonb->>'encounterId','92000000-0000-4000-8000-000000000004','targeted claim returns requested encounter');
select is(current_setting('test.job')::jsonb->'reports'->0->'fields'->0->>'value','10.4','claim uses frozen evidence, not subsequently changed report');
select is(api.demo_worker('claim','92000000-0000-4000-8000-000000000006')->'data','null'::jsonb,'active lease cannot be claimed twice');
select is(api.demo_worker('heartbeat','92000000-0000-4000-8000-000000000006',gen_random_uuid())->>'ok','false','wrong lease cannot heartbeat');
select is(api.demo_worker('heartbeat','92000000-0000-4000-8000-000000000006',(current_setting('test.job')::jsonb->>'lease')::uuid)->>'ok','true','current worker can renew lease');
reset role;
update phi.demo_jobs set lease_until=now()-interval '1 second' where id='92000000-0000-4000-8000-000000000006';
set local role service_role;
select is(api.demo_worker('complete','92000000-0000-4000-8000-000000000006',(current_setting('test.job')::jsonb->>'lease')::uuid,'{"urgency":"immediate"}')->>'ok','false','expired worker cannot publish');
select set_config('test.reclaimed',(api.demo_worker('claim','92000000-0000-4000-8000-000000000006')->'data')::text,true);
select isnt(current_setting('test.reclaimed')::jsonb->>'lease',current_setting('test.job')::jsonb->>'lease','recovery rotates lease');
select is(api.demo_worker('complete','92000000-0000-4000-8000-000000000006',(current_setting('test.job')::jsonb->>'lease')::uuid,'{"urgency":"immediate"}')->>'ok','false','old worker cannot publish after recovery');
select throws_ok($$select api.demo_worker('complete','92000000-0000-4000-8000-000000000006',(current_setting('test.reclaimed')::jsonb->>'lease')::uuid,'{"urgency":"review"}')$$,'P0001','Urgency below minimum','database prevents AI lowering deterministic floor');
select is(api.demo_worker('complete','92000000-0000-4000-8000-000000000006',(current_setting('test.reclaimed')::jsonb->>'lease')::uuid,'{"urgency":"immediate","syntheticSqlTest":true}')->>'ok','true','current lease publishes once');
select is(api.demo_worker('complete','92000000-0000-4000-8000-000000000006',(current_setting('test.reclaimed')::jsonb->>'lease')::uuid,'{"urgency":"immediate"}')->>'ok','false','duplicate completion rejected');
reset role;
select is((select status from phi.encounters where id='92000000-0000-4000-8000-000000000004'),'review_needed','AI completion never closes case');
-- A new source revision makes an in-flight result stale.
update phi.encounters set version=2,ai=null,ai_version=null,status='queued' where id='92000000-0000-4000-8000-000000000004';
insert into phi.demo_jobs(id,encounter_id,site_id,source_version) values('92000000-0000-4000-8000-000000000007','92000000-0000-4000-8000-000000000004','92000000-0000-4000-8000-000000000002',2);
set local role service_role;
select set_config('test.stale',(api.demo_worker('claim','92000000-0000-4000-8000-000000000007')->'data')::text,true);
reset role;
update phi.encounters set version=3 where id='92000000-0000-4000-8000-000000000004';
set local role service_role;
select is(api.demo_worker('complete','92000000-0000-4000-8000-000000000007',(current_setting('test.stale')::jsonb->>'lease')::uuid,'{"urgency":"immediate"}')->>'ok','false','superseded source cannot publish');
reset role;
insert into phi.demo_jobs(id,encounter_id,site_id,source_version) values('92000000-0000-4000-8000-000000000008','92000000-0000-4000-8000-000000000004','92000000-0000-4000-8000-000000000002',3);
set local role service_role;
select set_config('test.withdraw',(api.demo_worker('claim','92000000-0000-4000-8000-000000000008')->'data')::text,true);
select is(api.demo_worker('fail','92000000-0000-4000-8000-000000000008',(current_setting('test.withdraw')::jsonb->>'lease')::uuid,null,'model_unavailable')->>'ok','true','transient model outage is recorded');
select is(api.demo_worker('claim','92000000-0000-4000-8000-000000000008')->'data','null'::jsonb,'transient retry observes backoff');
reset role;
select ok((select status='queued' and available_at>now() from phi.demo_jobs where id='92000000-0000-4000-8000-000000000008'),'transient failure queues a delayed retry');
update phi.demo_jobs set available_at=now()-interval '1 second' where id='92000000-0000-4000-8000-000000000008';
set local role service_role;
select set_config('test.withdraw',(api.demo_worker('claim','92000000-0000-4000-8000-000000000008')->'data')::text,true);
reset role;
set local role anon;
select is(api.demo_action('withdraw','92000000-0000-4000-8000-000000000004',repeat('b',64))->>'ok','true','withdraw consent cancels active work');
select is(api.demo_action('get','92000000-0000-4000-8000-000000000004',repeat('b',64))->>'ok','false','withdrawal revokes patient access');
reset role;
set local role service_role;
select is(api.demo_worker('complete','92000000-0000-4000-8000-000000000008',(current_setting('test.withdraw')::jsonb->>'lease')::uuid,'{"urgency":"immediate"}')->>'ok','false','withdrawn consent prevents publication');
reset role;
select ok((select ai is null from phi.encounters where id='92000000-0000-4000-8000-000000000004'),'cancelled result remains absent');
select ok(exists(select 1 from audit.audit_events where action='demo_worker_complete' and outcome='denied_or_not_found' and record_ids=array['92000000-0000-4000-8000-000000000004'::uuid]),'rejected worker publication is audited');
select * from finish();
